"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, type ReactNode, useId, useMemo } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { duration, spring } from "@/lib/motion-tokens";
import { useChartInteraction } from "./chart-interaction";
import {
  chartAccentTransition,
  chartDraw,
  chartStaggerStep,
} from "./chart-motion";

export const thresholdBandChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[380px]",
      md: "max-w-[560px]",
      lg: "max-w-[720px]",
      full: "max-w-full",
    },
  },
  defaultVariants: { size: "md" },
});

export type ThresholdBand = {
  label: string;
  max?: number;
  tone?: string;
};

export type ThresholdBandChartProps = ComponentProps<"div"> &
  VariantProps<typeof thresholdBandChartVariants> & {
    bands?: ThresholdBand[];
    value?: number;
    title?: ReactNode;
    description?: ReactNode;
    totalMax?: number;
    unit?: string;
    valueFormatter?: (value: number) => string;
    animated?: boolean;
    showTooltip?: boolean;
    motionDelay?: number;
  };

const defaultBands: ThresholdBand[] = [
  { label: "Good", max: 2500, tone: "chart-2" },
  { label: "Needs improvement", max: 4000, tone: "chart-4" },
  { label: "Poor", tone: "destructive" },
];

function resolveTone(tone: string | undefined, fallback: string) {
  if (!tone) return fallback;
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(")
  )
    return tone;
  return `var(--${tone})`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(Math.max(v, lo), hi);
}

function defaultFormatter(v: number, unit: string) {
  if (unit === "ms") {
    return v >= 1000 ? `${(v / 1000).toFixed(2)}s` : `${Math.round(v)}ms`;
  }
  return `${v}${unit}`;
}

export function ThresholdBandChart({
  className,
  size,
  bands = defaultBands,
  value = 2800,
  title = "LCP Threshold",
  description = "Largest Contentful Paint — how fast your page feels",
  totalMax,
  unit = "ms",
  valueFormatter,
  animated = true,
  showTooltip = true,
  motionDelay = 0,
  ...props
}: ThresholdBandChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const motionEnabled = animated && !shouldReduceMotion;
  const fmt = (v: number) =>
    valueFormatter ? valueFormatter(v) : defaultFormatter(v, unit);

  // Normalize band maxes
  const resolvedBands = useMemo(() => {
    const maxes = bands.map((b) => b.max ?? null);
    // Auto total max = last defined max * 1.5
    const lastDefined = [...maxes].reverse().find((m) => m !== null);
    const auto = (lastDefined ?? 100) * 1.6;
    const safeTotal = totalMax ?? auto;

    let prev = 0;
    return bands.map((b) => {
      const end = b.max ?? safeTotal;
      const result = { ...b, start: prev, end, safeTotal };
      prev = end;
      return result;
    });
  }, [bands, totalMax]);

  const safeTotal = resolvedBands[resolvedBands.length - 1]?.safeTotal ?? 100;
  const {
    activeIndex: activeBandIndex,
    getItemProps,
    hasEnteredView,
    interactionProps,
  } = useChartInteraction(id, resolvedBands.length);
  const safeValue = clamp(value, 0, safeTotal);

  // Current band index
  const currentBandIndex = useMemo(() => {
    for (let i = 0; i < resolvedBands.length - 1; i++) {
      if (safeValue <= resolvedBands[i].end) return i;
    }
    return resolvedBands.length - 1;
  }, [resolvedBands, safeValue]);

  const currentBand = resolvedBands[currentBandIndex];

  // SVG layout
  const viewBoxWidth = 560;
  const viewBoxHeight = 178;
  const bandAreaX = 12;
  const bandAreaW = viewBoxWidth - 24;
  const bandY = 56;
  const bandH = 28;
  const bandRx = bandH / 2;

  const markerX = bandAreaX + (safeValue / safeTotal) * bandAreaW;

  const activeBand =
    activeBandIndex !== null ? resolvedBands[activeBandIndex] : null;
  const tooltipWidth = 168;
  const tooltipHeight = 58;
  const activeBandCenterX = activeBand
    ? bandAreaX +
      ((activeBand.start + activeBand.end) / 2 / safeTotal) * bandAreaW
    : markerX;
  const tooltipX = clamp(
    activeBandCenterX - tooltipWidth / 2,
    4,
    viewBoxWidth - tooltipWidth - 4,
  );
  const tooltipY = bandY + bandH + 28;
  const tooltipArrowX = clamp(
    activeBandCenterX - tooltipX,
    14,
    tooltipWidth - 14,
  );
  const activeBandRange = activeBand
    ? activeBandIndex === 0
      ? `≤ ${fmt(activeBand.end)}`
      : activeBandIndex === resolvedBands.length - 1
        ? `> ${fmt(activeBand.start)}`
        : `${fmt(activeBand.start)} – ${fmt(activeBand.end)}`
    : "";

  return (
    <div
      data-slot="threshold-band-chart"
      className={twMerge(thresholdBandChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="threshold-band-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div data-slot="threshold-band-chart-plot" className="overflow-hidden">
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="w-full"
            role="img"
            aria-labelledby={`${id}-title`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <defs>
              {resolvedBands.map((band, bi) => (
                <clipPath
                  key={`clip-${band.label}-${band.start}-${band.end}`}
                  id={`${id}-band-clip-${bi}`}
                >
                  <motion.rect
                    x={bandAreaX + (band.start / safeTotal) * bandAreaW}
                    y={bandY - 2}
                    height={bandH + 4}
                    rx={bandRx}
                    initial={
                      motionEnabled
                        ? { width: 0 }
                        : {
                            width:
                              ((band.end - band.start) / safeTotal) * bandAreaW,
                          }
                    }
                    animate={{
                      width: ((band.end - band.start) / safeTotal) * bandAreaW,
                    }}
                    transition={{
                      ...chartDraw(0.64),
                      delay: motionDelay + bi * chartStaggerStep,
                    }}
                  />
                </clipPath>
              ))}
            </defs>

            {/* Band segments */}
            {resolvedBands.map((band, bi) => {
              const bx = bandAreaX + (band.start / safeTotal) * bandAreaW;
              const bw = ((band.end - band.start) / safeTotal) * bandAreaW;
              const tone = resolveTone(band.tone, "var(--muted-foreground)");
              const isActive = activeBandIndex === bi;
              const isCurrent = currentBandIndex === bi;
              const accessibleRange =
                bi === 0
                  ? `up to ${fmt(band.end)}`
                  : bi === resolvedBands.length - 1
                    ? `above ${fmt(band.start)}`
                    : `${fmt(band.start)} to ${fmt(band.end)}`;

              return (
                <motion.g
                  key={`band-${band.label}-${band.start}-${band.end}`}
                  tabIndex={0}
                  role="button"
                  aria-label={`${band.label}: ${accessibleRange}`}
                  aria-describedby={
                    showTooltip && isActive ? `${id}-tooltip` : undefined
                  }
                  {...getItemProps(bi)}
                  style={{ cursor: "pointer" }}
                >
                  <rect
                    x={bx}
                    y={bandY}
                    width={bw}
                    height={bandH}
                    rx={bandRx}
                    fill={tone}
                    fillOpacity={
                      isCurrent
                        ? isActive
                          ? 0.28
                          : 0.2
                        : isActive
                          ? 0.16
                          : 0.1
                    }
                    clipPath={`url(#${id}-band-clip-${bi})`}
                  />
                  <motion.rect
                    x={bx}
                    y={bandY}
                    width={bw}
                    height={bandH}
                    rx={bandRx}
                    fill={tone}
                    fillOpacity={isCurrent ? 1 : 0.5}
                    stroke={isCurrent ? tone : "none"}
                    strokeWidth={isCurrent ? "0.5" : "0"}
                    clipPath={`url(#${id}-band-clip-${bi})`}
                    animate={{
                      fillOpacity: isCurrent
                        ? isActive
                          ? 0.82
                          : 0.62
                        : isActive
                          ? 0.45
                          : 0.3,
                    }}
                    transition={chartAccentTransition}
                  />
                  {/* Band label above */}
                  <motion.text
                    x={bx + bw / 2}
                    y={bandY - 10}
                    textAnchor="middle"
                    fill={tone}
                    fillOpacity={isCurrent ? 1 : 0.6}
                    className="text-[11px] font-semibold"
                    initial={
                      motionEnabled ? { opacity: 0, y: bandY - 4 } : false
                    }
                    animate={{ opacity: isCurrent ? 1 : 0.6, y: bandY - 10 }}
                    transition={{
                      ...chartAccentTransition,
                      delay: motionDelay + bi * chartStaggerStep + 0.3,
                    }}
                  >
                    {band.label}
                  </motion.text>
                  {/* Band max label */}
                  {bi < resolvedBands.length - 1 ? (
                    <text
                      x={bx + bw}
                      y={bandY + bandH + 14}
                      textAnchor="middle"
                      fill="var(--muted-foreground)"
                      className="text-[10px] font-medium tabular-nums"
                    >
                      {fmt(band.end)}
                    </text>
                  ) : null}
                </motion.g>
              );
            })}

            {/* Value marker */}
            <motion.g
              data-slot="threshold-band-chart-marker"
              initial={
                motionEnabled
                  ? { x: bandAreaX, opacity: 0 }
                  : { x: markerX - 1, opacity: 1 }
              }
              animate={{ x: markerX - 1, opacity: 1 }}
              transition={{
                x: { ...chartDraw(0.9), delay: motionDelay + 0.5 },
                opacity: {
                  delay: motionDelay + 0.5,
                  duration: duration.moderate,
                },
              }}
            >
              {/* Vertical line */}
              <line
                x1="1"
                x2="1"
                y1={bandY - 3}
                y2={bandY + bandH + 3}
                stroke="var(--foreground)"
                strokeWidth="2"
                strokeLinecap="round"
              />
              {/* Top diamond */}
              <polygon
                points="1,-4 5,0 1,4 -3,0"
                transform={`translate(0 ${bandY - 7})`}
                fill="var(--foreground)"
              />
              {/* Bottom label */}
              <motion.text
                x="1"
                y={bandY + bandH + 26}
                textAnchor="middle"
                fill="var(--foreground)"
                className="text-[12.5px] font-semibold tabular-nums"
                animate={{ opacity: activeBand ? 0 : 1 }}
                transition={{ duration: duration.fast }}
              >
                {fmt(safeValue)}
              </motion.text>
            </motion.g>

            {/* Active band tooltip */}
            <AnimatePresence>
              {showTooltip && activeBand ? (
                <motion.g
                  id={`${id}-tooltip`}
                  data-slot="threshold-band-chart-tooltip"
                  role="tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 5,
                          scale: 0.97,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 3,
                    scale: 0.97,
                  }}
                  transition={spring.fast}
                >
                  <path
                    d={`M ${tooltipArrowX - 6} 0 L ${tooltipArrowX} -7 L ${tooltipArrowX + 6} 0 Z`}
                    fill="var(--popover)"
                    stroke="var(--border)"
                    strokeLinejoin="round"
                  />
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="10"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <text
                    x="12"
                    y="22"
                    fill="var(--popover-foreground)"
                    className="text-[11px] font-semibold"
                  >
                    {activeBand.label}
                  </text>
                  <text
                    x="12"
                    y="40"
                    fill="var(--muted-foreground)"
                    className="text-[10px] font-medium"
                  >
                    Range
                  </text>
                  <text
                    x={tooltipWidth - 12}
                    y="40"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[10px] font-semibold tabular-nums"
                  >
                    {activeBandRange}
                  </text>
                  <text
                    x="12"
                    y="52"
                    fill="var(--muted-foreground)"
                    className="text-[10px] font-medium"
                  >
                    Current value
                  </text>
                  <text
                    x={tooltipWidth - 12}
                    y="52"
                    textAnchor="end"
                    fill={resolveTone(
                      currentBand?.tone,
                      "var(--muted-foreground)",
                    )}
                    className="text-[10px] font-semibold tabular-nums"
                  >
                    {fmt(safeValue)}
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import {
  duration,
  ease,
  spring,
  stagger,
} from "@/lib/motion-tokens";
import { surfaceClasses } from "@/lib/surface-classes";
import { useSurface } from "@/lib/surface-context";

/**
 * Shared motion for the SVG chart family, so twelve charts move on one system
 * instead of twelve hand-tuned timings.
 *
 * - A chart *tooltip* is a popover: it sits `offset` 2 above whatever substrate
 *   the chart is on, and it lands on the `fast` tier because a reading that
 *   trails the cursor reads as lag.
 * - An *accent* — a point growing, a bar highlighting, a ring blooming under
 *   hover — is micro-feedback, also `fast`.
 * - A *draw-on* — a line, an area, a bar revealing itself — is a shape over
 *   time, so it is a tween on `ease.decelerate`. Its length is data-scaled by
 *   the caller (a longer series draws longer); only the curve is fixed here.
 * - A whole chart *settling in* on scroll rides the same decelerate tween at
 *   the `slow` duration.
 */

/** The tooltip surface: `surfaceClasses` at the conventional popover offset. */
export function useChartTooltipSurface(): { level: number; className: string } {
  const level = Math.min(useSurface() + 2, 8);
  return { level, className: surfaceClasses(level) };
}

/** Tooltip enter/exit — spread onto the tooltip's `motion` element. */
export const chartTooltipMotion = {
  initial: { opacity: 0, y: 6, scale: 0.98 },
  animate: { opacity: 1, y: 0, scale: 1 },
  exit: { opacity: 0, y: 4, scale: 0.98, transition: spring.fast.exit },
  transition: spring.fast,
} as const;

/** Point / bar / segment accent under hover, focus or selection. */
export const chartAccentTransition = spring.fast;

/** A cursor line or crosshair fading in with the pointer. */
export const chartCursorTransition = {
  duration: duration.fast,
  ease: ease.standard,
};

/** Per-mark delay when a series staggers itself in (bars, points, bands). */
export const chartStaggerStep = stagger.moderate;

/** Tighter step for a dense grid or diagonal wave (a heatmap filling in), where
 *  `chartStaggerStep` across dozens of cells would drag. */
export const chartCascadeStep = stagger.fast;

/**
 * The draw-on transition. Pass the data-scaled length in seconds; the ease is
 * always `decelerate` so the reveal glides to a stop.
 */
export function chartDraw(seconds: number = duration.slow) {
  return { duration: seconds, ease: ease.decelerate } as const;
}

/** A whole chart or a band settling in when it scrolls into view. */
export const chartRevealTransition = {
  duration: duration.slow,
  ease: ease.decelerate,
} as const;
